def _lj_pair_parameters(sparam):
    """Resolve soft-LJ parameters to per-pair ``(i, j, epsilon, sigma, activation)``.

    Each of ``epsilon``, ``sigma`` and ``activation`` may be supplied either as
    a single shared value (``epsilon``) or as pair-specific values
    (``epsilon_i_j``); the two representations are detected independently for
    every parameter, exactly as the original parsing did.  Only the upper
    triangle (``i <= j``) is returned because a LAMMPS ``pair_coeff`` for
    ``(i, j)`` mirrors the off-diagonal automatically.
    """
    element_num = sparam.get("element_num", 1)
    sigma_key_index = [
        (i, j)
        for i in range(element_num)
        for j in range(element_num)
        if i <= j
    ]

    epsilon = sparam.get("epsilon", None)
    sigma = sparam.get("sigma", None)
    activation = sparam.get("activation", None)

    parameters = []
    for i, j in sigma_key_index:
        if epsilon is not None:
            assert sparam.get("epsilon_0_0", None) is None, (
                "epsilon and epsilon_0_0 cannot be set at the same time"
            )
            eps = epsilon
        else:
            assert sparam.get("epsilon_0_0", None) is not None, (
                "epsilon or epsilon_0_0 must be set"
            )
            eps = sparam["epsilon_" + str(i) + "_" + str(j)]

        if sigma is not None:
            assert sparam.get("sigma_0_0", None) is None, (
                "sigma and sigma_0_0 cannot be set at the same time"
            )
            sig = sigma
        else:
            assert sparam.get("sigma_0_0", None) is not None, (
                "sigma or sigma_0_0 must be set"
            )
            sig = sparam["sigma_" + str(i) + "_" + str(j)]

        if activation is not None:
            assert sparam.get("activation_0_0", None) is None, (
                "activation and activation_0_0 cannot be set at the same time"
            )
            act = activation
        else:
            assert sparam.get("activation_0_0", None) is not None, (
                "activation or activation_0_0 must be set"
            )
            act = sparam["activation_" + str(i) + "_" + str(j)]

        parameters.append((i, j, eps, sig, act))
    return parameters


def parse_lj_sigma_epsilon(ret, sparam, hybrid=False):
    pair_params = _lj_pair_parameters(sparam)
    if hybrid:
        pair_coeff_str = "lj/cut/soft "
    else:
        pair_coeff_str = ""

    for i, j, eps, sig, act in pair_params:
        ret += f"pair_coeff      {i + 1} {j + 1} {pair_coeff_str:s}{eps:f} {sig:f} {act:f}\n"
    return ret


def _soft_lj_fep_observable(sparam, direction):
    """Emit the dU/d(coupling) observable for a soft-LJ coupling stage.

    ``direction`` is ``"on"`` (every pair's epsilon scaled by ``LAMBDA``) or
    ``"off"`` (epsilon scaled by ``1 - LAMBDA``).  The LJ energy is linear in
    epsilon, so dU/d(coupling) equals the soft energy evaluated at full epsilon.
    That quantity is obtained, without dividing by the (possibly zero) coupling
    factor, as the ``compute fep`` perturbation energy for adding (``on``) or
    subtracting (``off``) each pair's full epsilon -- this is finite at the path
    boundaries (``LAMBDA = 0`` for ``on``, ``LAMBDA = 1`` for ``off``) and keeps
    the sign consistent with the path direction.
